-- BudoGraph P1B: reviewed current-state relational model.
-- Business UUIDs are generated by the trusted server with crypto.randomUUID().
-- Calendar dates are DATE; instants are TIMESTAMPTZ.
-- Owner/active-organizer consistency and active-assignee checks belong to future
-- transactional commands. Foreign keys preserve historical membership rows.

CREATE FUNCTION public.is_valid_event_timezone(value TEXT)
RETURNS BOOLEAN
LANGUAGE SQL
STABLE
SET search_path = pg_catalog
AS $$
  SELECT EXISTS (
    SELECT 1 FROM pg_catalog.pg_timezone_names
    WHERE name = value
      AND name !~ '^(posix/|right/)'
      AND name NOT IN ('localtime', 'posixrules')
  )
$$;

CREATE TABLE public.event (
  id UUID PRIMARY KEY,
  name TEXT NOT NULL CHECK (name ~ '[^[:space:]]'),
  start_date DATE NOT NULL CHECK (isfinite(start_date)),
  end_date DATE NOT NULL CHECK (isfinite(end_date)),
  timezone TEXT NOT NULL CHECK (public.is_valid_event_timezone(timezone)),
  owner_user_id TEXT NOT NULL REFERENCES public."user" (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  archived_at TIMESTAMPTZ CHECK (isfinite(archived_at)),
  version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP CHECK (isfinite(created_at)),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP CHECK (isfinite(updated_at)),
  CONSTRAINT event_date_order CHECK (end_date >= start_date)
);

CREATE TABLE public.event_member (
  id UUID PRIMARY KEY,
  event_id UUID NOT NULL REFERENCES public.event (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  user_id TEXT NOT NULL REFERENCES public."user" (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  access_role TEXT NOT NULL CHECK (access_role IN ('ORGANIZER', 'MEMBER')),
  operational_role TEXT NOT NULL DEFAULT '',
  active BOOLEAN NOT NULL DEFAULT TRUE,
  deactivated_at TIMESTAMPTZ CHECK (isfinite(deactivated_at)),
  version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP CHECK (isfinite(created_at)),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP CHECK (isfinite(updated_at)),
  CONSTRAINT event_member_user_unique UNIQUE (event_id, user_id),
  CONSTRAINT event_member_scope_unique UNIQUE (event_id, id),
  CONSTRAINT event_member_actor_scope_unique UNIQUE (event_id, id, user_id),
  CONSTRAINT event_member_deactivation_consistent CHECK (active = (deactivated_at IS NULL))
);

CREATE TABLE public.task (
  id UUID PRIMARY KEY,
  event_id UUID NOT NULL REFERENCES public.event (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  title TEXT NOT NULL CHECK (title ~ '[^[:space:]]'),
  category TEXT NOT NULL DEFAULT '',
  context TEXT NOT NULL DEFAULT '',
  deadline DATE NOT NULL CHECK (isfinite(deadline)),
  status TEXT NOT NULL DEFAULT 'not-started'
    CHECK (status IN ('not-started', 'in-progress', 'blocked', 'completed')),
  priority TEXT NOT NULL DEFAULT 'normal'
    CHECK (priority IN ('normal', 'important', 'critical')),
  assigned_member_id UUID,
  blocked_by TEXT NOT NULL DEFAULT '',
  blocks TEXT NOT NULL DEFAULT '',
  accepted_by_member_id UUID,
  accepted_at TIMESTAMPTZ CHECK (isfinite(accepted_at)),
  version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
  created_by UUID NOT NULL,
  updated_by UUID NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP CHECK (isfinite(created_at)),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP CHECK (isfinite(updated_at)),
  deleted_at TIMESTAMPTZ CHECK (isfinite(deleted_at)),
  deleted_by UUID,
  CONSTRAINT task_scope_unique UNIQUE (event_id, id),
  CONSTRAINT task_assignee_scope FOREIGN KEY (event_id, assigned_member_id)
    REFERENCES public.event_member (event_id, id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT task_acceptance_scope FOREIGN KEY (event_id, accepted_by_member_id)
    REFERENCES public.event_member (event_id, id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT task_creator_scope FOREIGN KEY (event_id, created_by)
    REFERENCES public.event_member (event_id, id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT task_updater_scope FOREIGN KEY (event_id, updated_by)
    REFERENCES public.event_member (event_id, id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT task_deleter_scope FOREIGN KEY (event_id, deleted_by)
    REFERENCES public.event_member (event_id, id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT task_acceptance_pair CHECK ((accepted_by_member_id IS NULL) = (accepted_at IS NULL)),
  CONSTRAINT task_acceptance_assignee CHECK (
    accepted_by_member_id IS NULL OR
    (assigned_member_id IS NOT NULL AND accepted_by_member_id = assigned_member_id)
  ),
  CONSTRAINT task_deletion_pair CHECK ((deleted_at IS NULL) = (deleted_by IS NULL))
);

CREATE TABLE public.activity_entry (
  id UUID PRIMARY KEY,
  event_id UUID NOT NULL REFERENCES public.event (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  actor_user_id TEXT NOT NULL REFERENCES public."user" (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  actor_member_id UUID,
  action_type TEXT NOT NULL CHECK (action_type ~ '[^[:space:]]'),
  target_type TEXT NOT NULL CHECK (target_type ~ '[^[:space:]]'),
  target_id UUID NOT NULL,
  payload JSONB NOT NULL DEFAULT '{}'::JSONB CHECK (jsonb_typeof(payload) = 'object'),
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP CHECK (isfinite(created_at)),
  CONSTRAINT activity_actor_scope FOREIGN KEY (event_id, actor_member_id, actor_user_id)
    REFERENCES public.event_member (event_id, id, user_id) ON DELETE RESTRICT ON UPDATE RESTRICT
);

CREATE INDEX event_owner_idx ON public.event (owner_user_id);
CREATE INDEX event_member_user_idx ON public.event_member (user_id, event_id);
CREATE INDEX task_event_deadline_idx ON public.task (event_id, deadline, id) WHERE deleted_at IS NULL;
CREATE INDEX task_event_assignee_idx ON public.task (event_id, assigned_member_id) WHERE deleted_at IS NULL;
CREATE INDEX activity_event_time_idx ON public.activity_entry (event_id, created_at, id);

-- One narrow history guard, not event sourcing or automatic business commands.
CREATE FUNCTION public.reject_activity_entry_mutation()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = pg_catalog
AS $$
BEGIN
  RAISE EXCEPTION 'Activity history is append-only.' USING ERRCODE = '55000';
END;
$$;

CREATE TRIGGER activity_entry_append_only
BEFORE UPDATE OR DELETE OR TRUNCATE ON public.activity_entry
FOR EACH STATEMENT EXECUTE FUNCTION public.reject_activity_entry_mutation();

-- Supabase exposes public tables through its Data API. With no policies these
-- tables deny direct anon/authenticated access. The trusted backend PostgreSQL
-- identity must have explicitly reviewed privileges; RLS does not replace its
-- authenticated Event-scoped authorization. No browser DB policies are added.
ALTER TABLE public."user" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.session ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.account ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.verification ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.event ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.event_member ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.task ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.activity_entry ENABLE ROW LEVEL SECURITY;
